'use strict';

// MODULES //

var isLayout = require( '@stdlib/blas/base/assert/is-layout' );
var isOperationSide = require( '@stdlib/blas/base/assert/is-operation-side' );
var isMatrixTriangle = require( '@stdlib/blas/base/assert/is-matrix-triangle' );
var isTransposeOperation = require( '@stdlib/blas/base/assert/is-transpose-operation' );
var isDiagonalType = require( '@stdlib/blas/base/assert/is-diagonal-type' );
var realf = require( '@stdlib/complex/float32/real' );
var imagf = require( '@stdlib/complex/float32/imag' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Solves one of the matrix equations `op(A)*X = alpha*B` or `X*op(A) = alpha*B`.
*
* @param {string} order - storage layout
* @param {string} side - specifies whether _A_ appears on the left or right
* @param {string} uplo - specifies whether upper or lower triangular part is used
* @param {string} transa - transpose operation applied to _A_
* @param {string} diag - specifies whether _A_ is unit triangular
* @param {NonNegativeInteger} M - number of rows in _B_
* @param {NonNegativeInteger} N - number of columns in _B_
* @param {Complex64} alpha - scalar constant
* @param {Complex64Array} A - input matrix
* @param {PositiveInteger} LDA - stride of the first dimension of _A_
* @param {Complex64Array} B - input/output matrix
* @param {PositiveInteger} LDB - stride of the first dimension of _B_
* @throws {TypeError} first argument must be a valid order
* @throws {TypeError} second argument must be a valid side
* @throws {TypeError} third argument must be a valid matrix triangle
* @throws {TypeError} fourth argument must be a valid transpose operation
* @throws {TypeError} fifth argument must be a valid diagonal type
* @throws {RangeError} sixth argument must be a nonnegative integer
* @throws {RangeError} seventh argument must be a nonnegative integer
* @throws {RangeError} tenth argument must be greater than or equal to max(1,nA)
* @throws {RangeError} twelfth argument must be greater than or equal to max(1,nB)
* @returns {Complex64Array} _B_
*/
function ctrsm( order, side, uplo, transa, diag, M, N, alpha, A, LDA, B, LDB ) { // eslint-disable-line max-params
	var isRowMajor;
	var alphaRe;
	var alphaIm;
	var isLeft;
	var nA;

	if ( !isLayout( order ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a valid order. Value: `%s`.', order ) );
	}
	if ( !isOperationSide( side ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be a valid side. Value: `%s`.', side ) );
	}
	if ( !isMatrixTriangle( uplo ) ) {
		throw new TypeError( format( 'invalid argument. Third argument must be a valid matrix triangle. Value: `%s`.', uplo ) );
	}
	if ( !isTransposeOperation( transa ) ) {
		throw new TypeError( format( 'invalid argument. Fourth argument must be a valid transpose operation. Value: `%s`.', transa ) );
	}
	if ( !isDiagonalType( diag ) ) {
		throw new TypeError( format( 'invalid argument. Fifth argument must be a valid diagonal type. Value: `%s`.', diag ) );
	}
	if ( M < 0 ) {
		throw new RangeError( format( 'invalid argument. Sixth argument must be a nonnegative integer. Value: `%d`.', M ) );
	}
	if ( N < 0 ) {
		throw new RangeError( format('invalid argument. Seventh argument must be a nonnegative integer. Value: `%d`.', N) );
	}
	isLeft = ( side === 'left' );
	isRowMajor = ( order === 'row-major' );
	nA = ( isLeft ) ? M : N;

	if ( isRowMajor ) {
		if ( LDA < nA ) {
			throw new RangeError( format( 'invalid argument. Tenth argument must be greater than or equal to max(1,%d). Value: `%d`.', nA, LDA ) );
		}
		if ( LDB < N ) {
			throw new RangeError( format( 'invalid argument. Twelfth argument must be greater than or equal to max(1,%d). Value: `%d`.', N, LDB ) );
		}
	} else {
		if ( LDA < nA ) {
			throw new RangeError( format( 'invalid argument. Tenth argument must be greater than or equal to max(1,%d). Value: `%d`.', nA, LDA ) );
		}
		if ( LDB < M ) {
			throw new RangeError( format( 'invalid argument. Twelfth argument must be greater than or equal to max(1,%d). Value: `%d`.', M, LDB ) );
		}
	}
	// Quick return if possible:
	if ( M === 0 || N === 0 ) {
		return B;
	}
	alphaRe = realf( alpha );
	alphaIm = imagf( alpha );

	// Delegate to ndarray interface:
	return ctrsm.ndarray(order, side, uplo, transa, diag, M, N, alphaRe, alphaIm, A, LDA, 0, B, LDB, 0);
}


// EXPORTS //

module.exports = ctrsm;
